/** Actual GUI choice, Survival packets, ownership and rendered sideways readers. */
final class ScreenChipLiveChecks {
    private static final BlockPos POS=new BlockPos(88,110,88);
    private static final String[] IDS={"programmable_diagonal_half_screen","programmable_diagonal_screen","programmable_half_console","programmable_console"};
    private static int ticks,stage,kind,wait;
    private static EntityPlayerMP player(Minecraft mc){return mc.getIntegratedServer().getPlayerList().getPlayers().get(0);}
    private static void server(Minecraft mc,Runnable work)throws Exception{mc.getIntegratedServer().addScheduledTask(work).get();}
    private static TileEntityAnimatedScreenSelector tile(World w){return (TileEntityAnimatedScreenSelector)w.getTileEntity(POS);}
    static boolean tick(Minecraft mc,File output)throws Exception{
        if(++ticks%8!=0)return false;mc.gameSettings.pauseOnLostFocus=false;
        if(++wait>100)throw new IllegalStateException("screen-chip timeout kind="+kind+" stage="+stage+" client-mode="+mc.player.isCreative()+" slot="+mc.player.inventory.currentItem+" held="+mc.player.getHeldItemMainhand());
        if(stage==0){mc.player.closeScreen();mc.player.inventory.currentItem=0;mc.getConnection().sendPacket(new net.minecraft.network.play.client.CPacketHeldItemChange(0));mc.playerController.setGameType(GameType.CREATIVE);server(mc,()->{
            EntityPlayerMP p=player(mc);WorldServer w=p.getServerWorld();p.interactionManager.setGameType(GameType.CREATIVE);p.inventory.currentItem=0;p.setHeldItem(EnumHand.MAIN_HAND,new ItemStack(ModItems.CONFIGURIZER));p.capabilities.isFlying=true;p.sendPlayerAbilities();
            for(BlockPos at:BlockPos.getAllInBox(POS.add(-2,-2,-2),POS.add(2,3,3)))w.setBlockToAir(at);w.setBlockState(POS,Block.getBlockFromName("vandorlabs:"+IDS[kind]).getDefaultState(),3);p.connection.setPlayerLocation(POS.getX()+.5,POS.getY()+.1,POS.getZ()-2,0,5);p.inventoryContainer.detectAndSendChanges();
        });next();return false;}
        if(stage==1){if(tile(mc.world)==null||!mc.player.isCreative()||mc.player.getHeldItemMainhand().getItem()!=ModItems.CONFIGURIZER)return false;
            server(mc,()->player(mc).openGui(com.vandorlabs.VandorLabs.instance,com.vandorlabs.GuiHandler.GUI_ANIMATED_SCREEN_SELECTOR,player(mc).world,POS.getX(),POS.getY(),POS.getZ()));next();return false;}
        if(stage==2){if(!(mc.currentScreen instanceof GuiContainer))return false;GuiContainer gui=(GuiContainer)mc.currentScreen;
            require(kind!=0||gui instanceof GuiProgrammableInput,"diagonal console GUI");require(kind!=2||gui instanceof GuiProgrammableHalfConsole,"half console GUI");
            ScreenTextureList textures=(ScreenTextureList)field(gui,kind==2?"topList":"screenList");HousingTextureList list=(HousingTextureList)field(textures,"list");
            if(kind==2){require((Integer)field(gui,"textureTab")==1,"Display must open first");HousingTextureList controls=(HousingTextureList)field(field(gui,"bottomList"),"list");require(field(controls,"chipAction")==null,"Chip leaked into Controls tab");}
            require(field(list,"chipAction")!=null,"Chip missing from Display picker");list.setSelected(TileEntityAnimatedScreenSelector.CHIP_SURFACE);
            @SuppressWarnings("unchecked") List<Integer> rows=(List<Integer>)field(list,"rows");int row=rows.indexOf(-100003);require(row>=0,"Chip row missing");int x=(Integer)field(list,"x")+8,y=(Integer)field(list,"y")+(row-(Integer)field(list,"scroll"))*HousingTextureList.ROW_HEIGHT+8;
            click(gui,x,y);captureGui(mc,output,"screen-chip-picker-"+kind);next();return false;}
        if(stage==3){int slot=ScreenChipSupport.displaySlot(tile(mc.world).getBlockType());if(!tile(mc.world).hasChipSurface(slot))return false;
            server(mc,()->{require(tile(player(mc).world).hasChipSurface(slot),"selection packet not authoritative");ownershipMatrix(player(mc).getServerWorld());});mc.player.closeScreen();mc.playerController.setGameType(GameType.SURVIVAL);
            server(mc,()->{EntityPlayerMP p=player(mc);p.interactionManager.setGameType(GameType.SURVIVAL);p.inventory.clear();p.inventory.currentItem=0;ItemStack chip=new ItemStack(ModItems.DATA_CHIP,2,3);if(kind==0)ChipJournal.write(chip,true,"Sideways Journal",new String[]{"First page","Second page"});if(kind==1){VehicleChip.blank(chip);VehicleShape.of(VehicleStructure.display(Arrays.asList(new VehicleStructure.Cell(BlockPos.ORIGIN,net.minecraft.init.Blocks.IRON_BLOCK.getDefaultState(),null),new VehicleStructure.Cell(BlockPos.ORIGIN.east(),net.minecraft.init.Blocks.STONE_SLAB.getDefaultState(),null),new VehicleStructure.Cell(BlockPos.ORIGIN.up(),net.minecraft.init.Blocks.GLASS.getDefaultState(),null)))).write(chip.getTagCompound());chip.getTagCompound().setString("VehicleName","Screen preview");}p.setHeldItem(EnumHand.MAIN_HAND,chip);MachineMountSurface mount=ScreenChipSupport.mount(p.world.getBlockState(POS),tile(p.world));p.world.setBlockState(POS.north(2),net.minecraft.init.Blocks.STONE.getDefaultState(),2);Vec3d target=new Vec3d(POS).add(mount.center),eye=new Vec3d(POS.getX()+.5,POS.getY()+1+p.getEyeHeight(),POS.getZ()-1.5);Vec3d d=target.subtract(eye);float yaw=(float)Math.toDegrees(Math.atan2(-d.x,d.z)),pitch=(float)-Math.toDegrees(Math.atan2(d.y,Math.sqrt(d.x*d.x+d.z*d.z)));p.connection.setPlayerLocation(eye.x,eye.y-p.getEyeHeight(),eye.z,yaw,pitch);p.inventoryContainer.detectAndSendChanges();});next();return false;}
        if(stage==4){if(mc.player.isCreative()||mc.player.inventory.currentItem!=0||mc.player.getHeldItemMainhand().getCount()!=2)return false;
            MachineMountSurface mount=ScreenChipSupport.mount(mc.world.getBlockState(POS),tile(mc.world));Vec3d target=new Vec3d(POS).add(mount.center);Vec3d direction=target.subtract(mc.player.getPositionEyes(1)).normalize();if(direction.dotProduct(Vec3d.fromPitchYaw(mc.player.rotationPitch,mc.player.rotationYaw))<.999)return false;
            require(mc.playerController.processRightClickBlock(mc.player,mc.world,POS,EnumFacing.getFacingFromVector((float)mount.normal.x,(float)mount.normal.y,(float)mount.normal.z),target,EnumHand.MAIN_HAND)==EnumActionResult.SUCCESS,"real insert click refused");next();return false;}
        if(stage==5){if(tile(mc.world).ownedChipReader().isEmpty())return false;server(mc,()->{EntityPlayerMP p=player(mc);require(p.getHeldItemMainhand().getCount()==1&&!tile(p.world).ownedChipReader().isEmpty(),"Survival insert duplicated/lost chip");});
            TileEntityAnimatedScreenSelector tile=tile(mc.world);BufferedImage first=render(mc,tile,0),last=render(mc,tile,12);require(different(first,last)>20,"sideways insertion did not animate");ImageIO.write(first,"png",new File(output,"screen-chip-"+kind+"-start.png"));ImageIO.write(last,"png",new File(output,"screen-chip-"+kind+"-inserted.png"));
            server(mc,()->{EntityPlayerMP p=player(mc);TileEntityAnimatedScreenSelector t=tile(p.world);int slot=ScreenChipSupport.displaySlot(t.getBlockType());ItemStack retained=t.ownedChipReader().getStackInSlot(0).copy();t.setSurfaceTexture(slot,-1);require(!ScreenChipSupport.selected(t)&&ItemStack.areItemStacksEqual(retained,t.ownedChipReader().getStackInSlot(0)),"hidden reader ownership");t.setSurfaceTexture(slot,TileEntityAnimatedScreenSelector.CHIP_SURFACE);p.inventory.currentItem=1;p.inventoryContainer.detectAndSendChanges();});mc.player.inventory.currentItem=1;mc.getConnection().sendPacket(new net.minecraft.network.play.client.CPacketHeldItemChange(1));next();return false;}
        if(stage==6){if(!mc.player.getHeldItemMainhand().isEmpty())return false;MachineMountSurface mount=ScreenChipSupport.mount(mc.world.getBlockState(POS),tile(mc.world));mc.playerController.processRightClickBlock(mc.player,mc.world,POS,EnumFacing.UP,new Vec3d(POS).add(mount.center),EnumHand.MAIN_HAND);next();return false;}
        if(stage==7){if(!tile(mc.world).ownedChipReader().isEmpty())return false;server(mc,()->{EntityPlayerMP p=player(mc);int count=0;for(ItemStack stack:p.inventory.mainInventory)if(stack.getItem()==ModItems.DATA_CHIP)count+=stack.getCount();require(count==2,"Survival removal did not return exactly one chip");});if(++kind<IDS.length){stage=0;wait=0;return false;}server(mc,()->attachedMatrix(player(mc).getServerWorld()));ScreenChipJoinedChecks.run(mc,output);System.out.println("[vandorlabs][reprolab] screen-chips PASS Display-only GUI packets Survival insert/remove hidden retention pose/upper matrices configured drops exact carried NBT all six external faces and sideways rendered animation");return true;}
        return false;
    }
    private static void next(){stage++;wait=0;}
    private static Object field(Object owner,String name)throws Exception{java.lang.reflect.Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
    private static void click(GuiContainer gui,int x,int y)throws Exception{if(gui instanceof GuiProgrammableInput)((GuiProgrammableInput)gui).mouseClicked(x,y,0);else if(gui instanceof GuiProgrammableHalfConsole)((GuiProgrammableHalfConsole)gui).mouseClicked(x,y,0);else ((GuiAnimatedScreenSelector)gui).mouseClicked(x,y,0);}
    private static void ownershipMatrix(WorldServer world){
        BlockPos at=POS.east(8);for(String id:IDS)for(EnumFacing facing:EnumFacing.HORIZONTALS)for(boolean upper:new boolean[]{false,true}){
            Block block=Block.getBlockFromName("vandorlabs:"+id);IBlockState state=block.getDefaultState();if(!(block instanceof BlockProgrammableDiagonalScreen))state=state.withProperty(BlockAnimatedScreenSelector.FACING,facing);if(block instanceof BlockProgrammableDiagonalScreen)state=block.getDefaultState().withProperty(BlockProgrammableDiagonalScreen.FACING,facing).withProperty(BlockProgrammableDiagonalScreen.INVERTED,upper);else if(block instanceof BlockDiagonalHalfConsole)state=state.withProperty(BlockDiagonalHalfConsole.UPPER,upper);
            world.setBlockState(at,state,2);TileEntityAnimatedScreenSelector t=(TileEntityAnimatedScreenSelector)world.getTileEntity(at);NBTTagCompound old=t.writeToNBT(new NBTTagCompound());require(!old.hasKey("ScreenChipReader"),"empty reader changed legacy NBT");VehicleStructure empty=VehicleStructure.display(Collections.singletonList(new VehicleStructure.Cell(at,state,old)));VehicleWorld emptyView=new VehicleWorld(world,empty);com.vandorlabs.copier.CopyMaterials.forSnapshot(empty,emptyView,false);VehicleWeight emptyWeight=new VehicleWeight(empty,emptyView);while(!emptyWeight.step(128,Long.MAX_VALUE)){}require(!emptyWeight.result().incomplete,"empty screen weight scan incomplete");try{require(field(emptyView.getTileEntity(at),"chipReader")==null,"empty screen scans allocated a chip reader");}catch(Exception failure){throw new IllegalStateException(failure);}
            int slot=ScreenChipSupport.displaySlot(block);require(ScreenChipSupport.available(t,slot)&&!ScreenChipSupport.available(t,1-slot),"Chip eligibility");t.setSurfaceTexture(slot,TileEntityAnimatedScreenSelector.CHIP_SURFACE);ItemStack chip=new ItemStack(ModItems.DATA_CHIP,1,4);ChipJournal.write(chip,true,"Stored",new String[]{"Exact data"});t.ownedChipReader().setInventorySlotContents(0,chip);
            MachineMountSurface mount=ScreenChipSupport.mount(state,t);require(Math.abs(mount.v.y)<1e-8&&mount.u.crossProduct(mount.v).dotProduct(mount.normal)<-.999,"reader is not sideways/right handed");require(mount.hit(mount.center.add(mount.normal.scale(2)),mount.center.subtract(mount.normal)),"slot ray missed authored frame");
            NBTTagCompound saved=t.writeToNBT(new NBTTagCompound());TileEntityAnimatedScreenSelector reload=new TileEntityAnimatedScreenSelector();reload.readFromNBT(saved);require(ItemStack.areItemStacksEqual(chip,reload.ownedChipReader().getStackInSlot(0))&&reload.hasChipSurface(slot),"reader reload");ItemStack drop=((BlockAnimatedScreenSelector)block).createConfiguredDrop(t);require(drop.getSubCompound("BlockEntityTag").getCompoundTag("ScreenChipReader").hasKey("InsertedToken"),"configured mining item lost chip");
            VehicleStructure snapshot=VehicleStructure.display(Collections.singletonList(new VehicleStructure.Cell(at,state,saved)));VehicleWorld view=new VehicleWorld(world,snapshot);TileEntityAnimatedScreenSelector carried=(TileEntityAnimatedScreenSelector)view.getTileEntity(at);require(ItemStack.areItemStacksEqual(chip,carried.ownedChipReader().getStackInSlot(0)),"vehicle view lost retained token");require(carried.writeToNBT(new NBTTagCompound()).equals(saved),"carried exact reader NBT changed");
            java.util.List<com.vandorlabs.copier.CopyMaterials.Need> needs=com.vandorlabs.copier.CopyMaterials.forSnapshot(snapshot,view,false);long chips=0;for(com.vandorlabs.copier.CopyMaterials.Need need:needs)if(com.vandorlabs.copier.CopyMaterials.matches(need.item,chip)&&need.exact)chips+=need.count;require(chips==1,"Survival copying must charge the exact embedded chip once");
            if(facing==EnumFacing.NORTH&&!upper){BlockPos copy=at.east(2);world.setBlockState(copy,state,2);com.vandorlabs.items.ProgrammableSettings.apply(world,copy,com.vandorlabs.items.ProgrammableSettings.capture(world,at));TileEntityAnimatedScreenSelector target=(TileEntityAnimatedScreenSelector)world.getTileEntity(copy);require(target.ownedChipReader().isEmpty(),"Duplifier duplicated a physical chip");world.setBlockToAir(copy);}
            com.vandorlabs.render.ScreenSurface.Quad q=RedstoneScreenInteractions.surface(state,t,slot);double across=(q.topRight.x-q.topLeft.x)/320,down=Math.hypot(q.bottomRight.y-q.topRight.y,q.bottomRight.z-q.topRight.z)/ScreenChipRenderer.height(q);require(Math.abs(across-down)/across<.005,"chip display stretched pixels/model");world.setBlockToAir(at);
        }
    }
    private static void attachedMatrix(WorldServer world){Block block=Block.getBlockFromName("vandorlabs:programmable_viewscreen");require(block!=null,"regular screen registered");world.setBlockState(POS,block.getDefaultState(),2);TileEntityAnimatedScreenSelector t=tile(world);require(!ScreenChipSupport.available(t,0),"regular screen offers chip without mount");for(EnumFacing face:EnumFacing.values()){BlockPos at=POS.offset(face);world.setBlockState(at,Block.getBlockFromName("vandorlabs:data_chip_slot").getDefaultState().withProperty(BlockVandorSwitch.FACING,face),2);TileEntityTokenSlot reader=(TileEntityTokenSlot)world.getTileEntity(at);ItemStack chip=new ItemStack(ModItems.DATA_CHIP,1,2);reader.setInventorySlotContents(0,chip);require(ScreenChipSupport.available(t,0)&&ScreenChipSupport.reader(t)==reader&&ItemStack.areItemStacksEqual(ScreenChipSupport.stack(t),chip),"attached mount face "+face);world.setBlockToAir(at);require(!ScreenChipSupport.available(t,0),"stale attached reader");}}
    private static void captureGui(Minecraft mc,File out,String name)throws Exception{mc.getFramebuffer().bindFramebuffer(true);mc.entityRenderer.setupOverlayRendering();mc.currentScreen.drawScreen(-1,-1,0);ImageIO.write(net.minecraft.util.ScreenShotHelper.createScreenshot(mc.displayWidth,mc.displayHeight,mc.getFramebuffer()),"png",new File(out,name+".png"));}
    private static BufferedImage render(Minecraft mc,TileEntityAnimatedScreenSelector tile,double age){Framebuffer f=new Framebuffer(400,300,true);GlStateManager.matrixMode(GL11.GL_PROJECTION);GlStateManager.pushMatrix();GlStateManager.loadIdentity();GlStateManager.ortho(-.8,.8,-.6,.6,-5,5);GlStateManager.matrixMode(GL11.GL_MODELVIEW);GlStateManager.pushMatrix();try(TurntableRenderState saved=new TurntableRenderState()){f.bindFramebuffer(true);GlStateManager.loadIdentity();GlStateManager.clearColor(.08F,.12F,.16F,1);GlStateManager.depthMask(true);GlStateManager.clear(16640);GlStateManager.enableDepth();GlStateManager.disableLighting();GlStateManager.disableFog();GlStateManager.disableCull();GlStateManager.rotate(25,1,0,0);GlStateManager.rotate(165,0,1,0);GlStateManager.translate(-.5,tile.getBlockType() instanceof BlockProgrammableDiagonalScreen?-.65:-.3,-.5);NBTTagCompound token=tile.ownedChipReader().writeEmbedded();tile.ownedChipReader().readEmbedded(new NBTTagCompound());TokenSlotVisualMotion.ageAt(tile.ownedChipReader(),999);tile.ownedChipReader().readEmbedded(token);TokenSlotVisualMotion.ageAt(tile.ownedChipReader(),1000);TokenSlotVisualMotion.at(1000+age,()->new TEAnimatedScreenSelector().render(tile,0,0,0,0,-1,1));return net.minecraft.util.ScreenShotHelper.createScreenshot(400,300,f);}finally{GlStateManager.popMatrix();GlStateManager.matrixMode(GL11.GL_PROJECTION);GlStateManager.popMatrix();GlStateManager.matrixMode(GL11.GL_MODELVIEW);f.deleteFramebuffer();mc.getFramebuffer().bindFramebuffer(true);}}
    private static int different(BufferedImage a,BufferedImage b){int count=0;for(int y=0;y<a.getHeight();y++)for(int x=0;x<a.getWidth();x++)if(a.getRGB(x,y)!=b.getRGB(x,y))count++;return count;}
    private static void require(boolean value,String message){if(!value)throw new IllegalStateException(message);}
}
